    overview: { policiesTotal: 0, policiesActive: 0, tenantsTotal: 0, keysTotal: 0, keysActive: 0, providerCount: 3, openaiCompatibleProviders: 0, manifestRoutes: 0, monthlyBudgetMicros: 0, requestCostMicros: 0 },
